def get_h(k, a):
    res = 0
    temp = k
    for p, val in a.items():
        while temp % p == 0:
            res += val
            temp //= p
    return res

def check_h(n, a):
    for k in range(1, n):
        if get_h(k, a) != get_h(n-k, a):
            return False
    return True

# Try to find a and n such that check_h(n, a) is True
# a is a dictionary of {prime: value}
primes = [2, 3, 5, 7, 11, 13]
import itertools

# Search for a and n
for n in range(2, 20):
    # Try small values for a_i
    for vals in itertools.product([-1, 0, 1], repeat=len(primes)):
        a = {primes[i]: vals[i] for i in range(len(primes))}
        if any(vals):
            if check_h(n, a):
                print(f"n={n}, a={a}")
